/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Btn_PrintInputs */

const en_btn_print = /** @type {(inputs: Btn_PrintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Print Document`)
};

const vi_btn_print = /** @type {(inputs: Btn_PrintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`In Văn bản`)
};

/**
* | output |
* | --- |
* | "Print Document" |
*
* @param {Btn_PrintInputs} inputs
* @param {{ locale?: "en" | "vi" }} options
* @returns {LocalizedString}
*/
export const btn_print = /** @type {((inputs?: Btn_PrintInputs, options?: { locale?: "en" | "vi" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Btn_PrintInputs, { locale?: "en" | "vi" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "vi") return vi_btn_print(inputs)
	return en_btn_print(inputs)
});